"""Run sql/02_analysis.sql and write the results to docs/03-analysis-results.md."""
import re
import sqlite3
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
con = sqlite3.connect(ROOT / "data" / "zomato.db")
blocks = re.split(r"^-- name: ", (ROOT / "sql" / "02_analysis.sql").read_text(encoding="utf-8"), flags=re.M)[1:]

out = ["# Analysis results", "",
       "Generated by `scripts/run_analysis.py`. Rating averages only include rated restaurants.", ""]
for b in blocks:
    head, _, body = b.partition("\n")
    title = head.split("|", 1)[1].strip()
    cur = con.execute(body)
    cols = [d[0] for d in cur.description]
    out += [f"## {title}", "", "| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    out += ["| " + " | ".join("" if v is None else str(v) for v in r) + " |" for r in cur.fetchall()]
    out.append("")
(ROOT / "docs" / "03-analysis-results.md").write_text("\n".join(out), encoding="utf-8")
print("ok")
